import AppKit
import SwiftUI
enum PhotoDecor {
 static let colors=[NSColor(red:240/255,green:224/255,blue:213/255,alpha:1),NSColor(red:219/255,green:210/255,blue:236/255,alpha:1),NSColor(red:220/255,green:231/255,blue:211/255,alpha:1)]
 static func encode(_ image:NSImage)throws->Data{let scale=min(1,1600/max(image.size.width,image.size.height));let w=max(1,Int(image.size.width*scale)),h=max(1,Int(image.size.height*scale));guard let rep=NSBitmapImageRep(bitmapDataPlanes:nil,pixelsWide:w,pixelsHigh:h,bitsPerSample:8,samplesPerPixel:3,hasAlpha:false,isPlanar:false,colorSpaceName:.deviceRGB,bytesPerRow:0,bitsPerPixel:0),let context=NSGraphicsContext(bitmapImageRep:rep)else{throw WindowsCompatibility.fail("사진을 준비하지 못했어요.")};NSGraphicsContext.saveGraphicsState();NSGraphicsContext.current=context;NSColor.white.setFill();NSRect(x:0,y:0,width:CGFloat(w),height:CGFloat(h)).fill();image.draw(in:NSRect(x:0,y:0,width:CGFloat(w),height:CGFloat(h)));NSGraphicsContext.restoreGraphicsState();guard let data=rep.representation(using:.jpeg,properties:[.compressionFactor:0.88]),data.count<=2*1024*1024 else{throw WindowsCompatibility.fail("사진은 편집 후 2MB 이하여야 해요.")};try WindowsCompatibility.checkPhoto(data);return data}
 static func render(_ size:NSSize,_ draw:()->Void)->NSImage{let image=NSImage(size:size);image.lockFocus();NSColor.white.setFill();NSRect(origin:.zero,size:size).fill();draw();image.unlockFocus();return image}
 static func crop(_ image:NSImage,ratio:Double)->NSImage {var size=image.size;if size.width/size.height>ratio{size.width=size.height*ratio}else{size.height=size.width/ratio};return render(size){image.draw(in:NSRect(x:(size.width-image.size.width)/2,y:(size.height-image.size.height)/2,width:image.size.width,height:image.size.height))}}
 static func rotate(_ image:NSImage,clockwise:Bool)->NSImage{let size=NSSize(width:image.size.height,height:image.size.width);return render(size){let t=NSAffineTransform();t.translateX(by:size.width/2,yBy:size.height/2);t.rotate(byDegrees:clockwise ? -90:90);t.concat();image.draw(in:NSRect(x:-image.size.width/2,y:-image.size.height/2,width:image.size.width,height:image.size.height))}}
 static func frame(_ image:NSImage,color:Int)->NSImage{let edge=max(6,min(image.size.width,image.size.height)/16);let scale=min(1,1600/(max(image.size.width,image.size.height)+2*edge));let size=NSSize(width:(image.size.width+2*edge)*scale,height:(image.size.height+2*edge)*scale);return render(size){colors[color].setFill();NSRect(origin:.zero,size:size).fill();image.draw(in:NSRect(x:edge*scale,y:edge*scale,width:image.size.width*scale,height:image.size.height*scale))}}
 static func stamp(_ kind:Int,in rect:NSRect){NSGraphicsContext.saveGraphicsState();defer{NSGraphicsContext.restoreGraphicsState()};let t=NSAffineTransform();t.translateX(by:rect.minX,yBy:rect.minY);t.scaleX(by:rect.width/100,yBy:rect.height/100);t.concat();let pink=NSColor(red:227/255,green:156/255,blue:168/255,alpha:1),yellow=NSColor(red:239/255,green:205/255,blue:125/255,alpha:1);switch kind{case 0:pink.setFill();for i in 0..<6{let a=Double(i)*Double.pi/3;NSBezierPath(ovalIn:NSRect(x:32+cos(a)*23,y:32+sin(a)*23,width:36,height:36)).fill()};yellow.setFill();NSBezierPath(ovalIn:NSRect(x:35,y:35,width:30,height:30)).fill();case 1:pink.setFill();let p=NSBezierPath();p.move(to:NSPoint(x:50,y:15));p.curve(to:NSPoint(x:28,y:86),controlPoint1:NSPoint(x:0,y:50),controlPoint2:NSPoint(x:2,y:90));p.curve(to:NSPoint(x:50,y:71),controlPoint1:NSPoint(x:42,y:86),controlPoint2:NSPoint(x:49,y:76));p.curve(to:NSPoint(x:92,y:70),controlPoint1:NSPoint(x:55,y:96),controlPoint2:NSPoint(x:87,y:94));p.curve(to:NSPoint(x:50,y:15),controlPoint1:NSPoint(x:100,y:50),controlPoint2:NSPoint(x:70,y:27));p.close();p.fill();case 2:yellow.setFill();let p=NSBezierPath();for i in 0..<10{let a=Double(i)*Double.pi/5+Double.pi/2;let r:Double=i%2==0 ? 44:20;let point=NSPoint(x:50+cos(a)*r,y:50+sin(a)*r);if i==0{p.move(to:point)}else{p.line(to:point)}};p.close();p.fill();default:NSColor(red:122/255,green:148/255,blue:110/255,alpha:1).setFill();let t=NSAffineTransform();t.rotate(byDegrees:8);t.concat();NSRect(x:8,y:35,width:80,height:30).fill();NSColor(red:221/255,green:231/255,blue:207/255,alpha:1).setStroke();for i in stride(from:15,to:85,by:15){let p=NSBezierPath();p.lineWidth=3;p.move(to:NSPoint(x:CGFloat(i),y:36));p.line(to:NSPoint(x:CGFloat(i+9),y:64));p.stroke()}}}
 static func sticker(_ kind:Int)->NSImage{render(NSSize(width:320,height:240)){NSColor(red:250/255,green:248/255,blue:243/255,alpha:1).setFill();NSRect(x:0,y:0,width:320,height:240).fill();stamp(kind,in:NSRect(x:60,y:20,width:200,height:200))}}
}
struct PhotoDecorView:View {
 let source:Data;let apply:(Data)->Void
 @Environment(\.dismiss)private var dismiss
 @State private var image:NSImage?;@State private var sticker = -1;@State private var message=""
 var body:some View {VStack(alignment:.leading,spacing:12){Text("사진 꾸미기").font(.title2);Text("스티커를 고른 뒤 사진에서 붙일 위치를 눌러요.");Text(message).foregroundStyle(.red)
  GeometryReader{geometry in if let image{Image(nsImage:image).resizable().scaledToFit().frame(width:geometry.size.width,height:geometry.size.height).contentShape(Rectangle()).gesture(DragGesture(minimumDistance:0).onEnded{value in guard sticker>=0 else{return};let size=image.size;let scale=min(geometry.size.width/size.width,geometry.size.height/size.height);let x=(value.location.x-(geometry.size.width-size.width*scale)/2)/scale;let y=size.height-(value.location.y-(geometry.size.height-size.height*scale)/2)/scale;guard x>=0,y>=0,x<size.width,y<size.height else{return};let side=min(size.width,size.height)*0.22;self.image=PhotoDecor.render(size){image.draw(in:NSRect(origin:.zero,size:size));PhotoDecor.stamp(sticker,in:NSRect(x:x-side/2,y:y-side/2,width:side,height:side))}})}}.frame(height:300)
  HStack{Button("왼쪽 회전"){if let image{self.image=PhotoDecor.rotate(image,clockwise:false)}};Button("오른쪽 회전"){if let image{self.image=PhotoDecor.rotate(image,clockwise:true)}};Button("정사각 자르기"){if let image{self.image=PhotoDecor.crop(image,ratio:1)}};Button("4:3 자르기"){if let image{self.image=PhotoDecor.crop(image,ratio:4.0/3)}}}
  HStack{ForEach(0..<3){i in Button(["크림","라벤더","숲"][i]+" 테두리"){if let image{self.image=PhotoDecor.frame(image,color:i)}}}}
  Picker("붙일 스티커",selection:$sticker){Text("선택 안 함").tag(-1);ForEach(0..<4){i in Text(StudioCatalog.stickers[i]).tag(i)}}.pickerStyle(.segmented)
  HStack{Button("처음으로"){image=NSImage(data:source)};Button("취소"){dismiss()};Spacer();Button("이 사진 적용"){do{if let image{apply(try PhotoDecor.encode(image));dismiss()}}catch{message=error.localizedDescription}}}
 }.padding(22).frame(width:760,height:610).background(DesktopPalette.sidebar).onAppear{image=NSImage(data:source)}}
}
